import{STATIONS}from'./navigation.mjs';
export const TICKETING={provider:'Weezevent',status:'coming-soon',checkoutUrl:null};
export const ARTISTS=[['NARA VOSS','HYPNOTIC HOUSE','Bajos profundos. Percusión rota. Cero prisa.','Deep bass. Broken percussion. No rush.'],['SAL NEGRA','LIVE / ALT ROCK','Guitarras crudas y un directo sin filtro.','Raw guitars and an unfiltered live show.'],['CORA SUR','REGGAETON / CLUB','Ritmos latinos que miran hacia el futuro.','Latin rhythms with an eye on the future.'],['DUST RADIO','COUNTRY / LIVE','Cuerdas, polvo y horizontes abiertos.','Strings, dust and open horizons.'],['MILO TIDE','ELECTRO / TECHNO','Texturas analógicas hasta la última señal.','Analogue textures until the last signal.']];
export const GALLERY=[{src:'assets/beach-demo.webp',es:'La playa, nuestra pista.',en:'The beach is our dancefloor.'},{src:'assets/decks-demo.webp',es:'Sesiones a bordo.',en:'Sessions on board.'},{src:'assets/hero.webp',es:'Sigue la señal.',en:'Follow the signal.'}];
const instagram='<a class="primary" href="https://www.instagram.com/boia.planet/" target="_blank" rel="noopener">@boia.planet <span>↗</span></a>';
export function panelHTML(id,lang,seen=new Set()){
 const es=lang==='es',t=(a,b)=>es?a:b;
 const wrapper=(k,h,body)=>`<div class="panel-inner"><div class="panel-kicker">${k}</div><h2 id="panel-title">${h}</h2>${body}</div>`;
 if(id.startsWith('photo-')){const n=Number(id.slice(6));if(!Number.isInteger(n)||!GALLERY[n])return '';const photo=GALLERY[n];return wrapper(t('DIARIO VISUAL / IMAGEN DE MUESTRA','VISUAL DIARY / DEMO IMAGE'),photo[lang],`<figure class="gallery-view"><img src="${photo.src}" alt="${photo[lang]}"></figure><p class="fine">${t('Imagen generada para esta propuesta. No documenta un evento real de BOIA.','Image generated for this proposal. It does not document a real BOIA event.')}</p><div class="gallery-controls"><button class="outline" data-open="photo-${(n+GALLERY.length-1)%GALLERY.length}">${t('← Anterior','← Previous')}</button><button class="outline" data-open="photo-${(n+1)%GALLERY.length}">${t('Siguiente →','Next →')}</button><button class="outline" data-open="archive">${t('Volver al archivo','Back to archive')}</button></div>`);}
 if(id==='destinations')return wrapper(t('CARTA NÁUTICA / SEIS SEÑALES','SEA CHART / SIX SIGNALS'),t('ELIGE<br>TU RUMBO.','CHOOSE<br>YOUR COURSE.'),`<p>${t('Toca un destino para descubrirlo o traza una ruta y navega hasta su boya.','Tap a destination to discover it, or set a course and sail to its buoy.')}</p><div class="destination-list">${STATIONS.map(s=>`<button class="destination-item" data-open="${s.id}" style="--station:${s.color}"><i>${seen.has(s.id)?'✓':s.n}</i><div><strong>${s[lang]}</strong><small>${es?s.subEs:s.subEn}</small></div><span>↗</span></button>`).join('')}</div><a class="backlink" href="festival.html">${t('Ver toda la web sin jugar ↗','View the website without playing ↗')}</a>`);
 if(id==='help')return wrapper('BOIA / SEA EXPLORER',t('TÚ LLEVAS<br>EL TIMÓN.','YOU’RE<br>AT THE HELM.'),`<p class="intro">${t('Navega libremente. Acércate a las boyas de colores y descubre qué hay detrás de cada señal.','Sail freely. Approach the coloured buoys and discover what lies behind each signal.')}</p><div class="help-keys"><div><b>W / ↑ · S / ↓</b><span>${t('Avanzar · Marcha atrás','Forward · Reverse')}</span></div><div><b>A / ← · D / →</b><span>${t('Girar a izquierda · derecha','Turn left · right')}</span></div><div><b>SHIFT · ESPACIO</b><span>${t('Turbo · Frenar','Boost · Brake')}</span></div><div><b>E / ENTER</b><span>${t('Abrir boya cercana','Open nearby buoy')}</span></div><div><b>M · R</b><span>${t('Mapa · Volver al inicio','Map · Return to start')}</span></div><div><b>${t('MÓVIL','MOBILE')}</b><span>${t('Mantén pulsado el barco y arrastra. También hay joystick fijo y turbo.','Hold the boat and drag. A fixed joystick and boost button are also available.')}</span></div></div><p>${t('Al pulsar el barco, el joystick aparece justo bajo tu dedo o cursor. Arrastra hacia donde quieras navegar; cuanto más lejos, más aceleras. Suelta para dejar de acelerar. También puedes tocar el agua o una boya para activar el piloto automático. El teclado o joystick recuperan el control. La brújula alterna entre el mapa completo y la cámara del barco.','Hold the boat to place a joystick under your finger or cursor. Drag towards your destination; drag further to accelerate more. Release to stop accelerating. You can also tap the water or a buoy to activate autopilot. The keyboard or joystick returns control to you. The compass switches between the full map and the boat camera.')}</p><button class="outline" data-reset>${t('Volver a puerto','Return to harbour')}</button><button class="outline" data-camera>${t('Cambiar cámara','Switch camera')}</button><p class="fine">${t('El sonido es opcional y se activa con el altavoz. Este mundo y su programación son una propuesta creativa; no representan lugares ni eventos confirmados.','Sound is optional and enabled with the speaker. This world and its programme are a creative concept, not confirmed locations or events.')}</p>`);
 const s=STATIONS.find(s=>s.id===id);if(!s)return '';
 let body='',h='';
 if(id==='manifesto'){h=t('SIGUE<br>LA SEÑAL.','FOLLOW<br>THE SIGNAL.');body=`<img class="panel-mascot" src="assets/mascot.jpeg" alt="BOIA"><p class="intro">${t('Un punto de encuentro. Ningún género obligatorio.','A meeting point. No mandatory genre.')}</p><p>${t('BOIA es un festival underground para artistas emergentes y consolidados de cualquier parte del mundo. La electrónica marca el pulso. El reguetón, el rock, el country y la música en directo abren el horizonte.','BOIA is an underground festival for emerging and established artists from all over the world. Electronic music sets the pulse. Reggaeton, rock, country and live music open up the horizon.')}</p><h3>${t('TALENTO SIN FRONTERAS.','TALENT WITHOUT BORDERS.')}</h3><p>${t('Ven a descubrir algo que todavía no conoces. A compartir espacio. A escuchar de otra manera. Aquí caben muchas frecuencias.','Come to discover something you don’t know yet. To share a space. To listen differently. There’s room for many frequencies here.')}</p>`;}
 if(id==='artists'){h=t('TODOS<br>A BORDO.','ALL<br>ABOARD.');body=`<p class="intro">${t('Una cabina flotante. Un escenario abierto al mundo.','A floating booth. A stage open to the world.')}</p><p class="fine">${t('SELECCIÓN DE DEMOSTRACIÓN · Artistas ficticios, sin actuaciones confirmadas.','DEMO SELECTION · Fictional artists, no confirmed performances.')}</p>${ARTISTS.map(a=>`<article class="artist-card"><strong>${a[0]}</strong><small>${a[1]}</small><p>${a[es?2:3]}</p></article>`).join('')}<h3>${t('¿TIENES ALGO QUE SONAR?','GOT A SOUND TO SHARE?')}</h3><p>${t('Cuéntanos lo que haces. BOIA también va de descubrirte.','Tell us what you do. BOIA is about discovering you, too.')}</p>${instagram}`;}
 if(id==='tickets'){h=t('TU PRÓXIMO<br>EMBARQUE.','YOUR NEXT<br>DEPARTURE.');body=`<p class="intro">${t('La próxima edición todavía está tomando forma.','The next edition is still taking shape.')}</p><div class="status-card"><span class="status"><i class="live-dot"></i>${t('VENTA NO DISPONIBLE','SALES NOT OPEN')}</span><strong>${t('PRÓXIMAMENTE','COMING SOON')}</strong><p>${t('Fecha, horarios y precios por anunciar. Aquí encontrarás las entradas cuando se abra la venta.','Date, times and prices to be announced. Tickets will appear here when sales open.')}</p></div><button class="primary checkout-button" disabled>${t('Comprar entradas · próximamente','Buy tickets · coming soon')}</button><p>${t('La venta se activará aquí al anunciar la siguiente edición. Sigue la próxima señal en Instagram.','Sales will open here when the next edition is announced. Follow the next signal on Instagram.')}</p>${instagram}<h3>${t('¿DÓNDE NOS VEMOS?','WHERE DO WE MEET?')}</h3><p>${t('La zona general se anuncia antes. La dirección exacta se comparte de forma privada con quienes tengan entrada.','The general area is announced first. The exact address is shared privately with ticket holders.')}</p><p class="fine">${t('No se realizan compras ni reservas desde esta demostración.','No purchases or reservations can be made in this demo.')}</p>`;}
 if(id==='beach'){h=t('MÁS ALLÁ<br>DE LA PISTA.','BEYOND THE<br>DANCEFLOOR.');body=`<p class="intro">${t('Hay encuentros que empiezan con un tema y terminan alrededor de una mesa.','Some encounters begin with a track and end around a table.')}</p><h3>01 / ${t('MESA LARGA','THE LONG TABLE')}</h3><p>${t('Paella, gastronomía y sobremesas. La excusa perfecta para acabar conociendo a quien bailaba a tu lado.','Paella, food and long conversations. The perfect excuse to meet whoever was dancing next to you.')}</p><h3>02 / ${t('DIRECTO Y SIN FILTRO','LIVE AND UNFILTERED')}</h3><p>${t('DJ sets y música en directo. Una banda, una voz, un cambio de energía.','DJ sets and live music. A band, a voice, a shift in energy.')}</p><h3>03 / ${t('LLÉVATE UN TROZO','TAKE A PIECE HOME')}</h3><p>${t('Gráfica independiente, merchandising y colaboraciones artísticas. Pequeñas señales que siguen contigo.','Independent graphics, merchandise and artistic collaborations. Small signals that stay with you.')}</p><p class="fine">${t('Actividades propuestas. La programación final se anunciará con cada edición.','Proposed activities. The final programme will be announced with each edition.')}</p>`;}
 if(id==='archive'){h=t('QUEDA<br>EL ECO.','THE ECHO<br>REMAINS.');body=`<p class="intro">${t('Cada encuentro deja una marca. Este es el primer boceto de nuestro archivo.','Every gathering leaves a mark. This is the first sketch of our archive.')}</p><p class="fine">${t('GALERÍA DE MUESTRA · Imágenes generadas, no fotografías de eventos reales.','DEMO GALLERY · Generated images, not photos of real events.')}</p><div class="panel-gallery">${GALLERY.map((p,i)=>`<button data-open="photo-${i}"><img src="${p.src}" alt="${p[lang]}" loading="lazy" width="1200" height="800"><span>0${i+1} / ${p[lang]} ↗</span></button>`).join('')}</div><h3>${t('EL ARCHIVO GRÁFICO','THE GRAPHIC ARCHIVE')}</h3><div class="gallery-poster"><div class="mini-poster"><small>BOIA / 001</small><b>DEEP<br>IN THE<br>BLUE.</b><small>CONCEPT EDITION</small></div><div class="mini-poster"><small>BOIA / 002</small><b>OFF<br>THE<br>RADAR.</b><small>CONCEPT EDITION</small></div><div class="mini-poster"><small>BOIA / 003</small><b>NO FIXED<br>FREQUENCY.</b><small>CONCEPT EDITION</small></div></div><img class="panel-image" src="assets/hero.webp" alt="${t('Visual conceptual de una boya sobre el mar','Concept visual of a buoy at sea')}"><p class="fine">${t('Carteles y visuales conceptuales. Sustituiremos estas piezas por fotos, vídeos y carteles reales de BOIA.','Concept posters and visuals. These will be replaced with real BOIA photos, videos and posters.')}</p><a class="outline" href="festival.html#gallery">${t('Abrir galería ↗','Open gallery ↗')}</a><div class="status-card"><span class="status">BOIA FILMS</span><strong>${t('AFTERMOVIE POR VENIR','AFTERMOVIE TO COME')}</strong><p>${t('De momento, la historia se está escribiendo.','For now, the story is still being written.')}</p></div>`;}
 if(id==='secret'){h='SECRET<br>LOCATION.';body=`<p class="intro">${t('La zona se anuncia. El punto exacto se revela.','The area is announced. The exact point is revealed.')}</p><div class="status-card"><span class="status">—° —′ —″ N / —° —′ —″ E</span><strong>${t('FUERA DEL RADAR','OFF THE RADAR')}</strong><p>${t('Próxima zona por confirmar. La ubicación del juego es imaginaria.','Next area to be confirmed. The game location is imaginary.')}</p></div><p>${t('Quienes tengan entrada recibirán la dirección exacta por un canal privado cuando se confirme la edición.','Ticket holders will receive the exact address through a private channel once the edition is confirmed.')}</p><h3>${t('MANDA UNA SEÑAL.','SEND A SIGNAL.')}</h3><p>${t('Público, artistas y colaboraciones: hablamos por Instagram.','Audience, artists and collaborations: let’s talk on Instagram.')}</p>${instagram}`;}
 return wrapper(`${s.n} / ${s[lang]}`,h,body+`<div class="route-description"><button class="primary" data-sail="${id}">${t('Navegar hasta aquí','Sail here')} <span>↗</span></button><button class="outline" data-open="destinations">${t('Todos los destinos','All destinations')}</button></div>`);
}
